<script>
import BaseComponent from '@primevue/core/basecomponent';
import ScrollAreaCornerStyle from 'primevue/scrollareacorner/style';

export default {
    name: 'BaseScrollAreaCorner',
    extends: BaseComponent,
    props: {
        as: {
            type: [String, Object],
            default: 'DIV'
        },
        asChild: {
            type: Boolean,
            default: false
        }
    },
    style: ScrollAreaCornerStyle,
    provide() {
        return {
            $pcScrollAreaCorner: this,
            $parentInstance: this
        };
    }
};
</script>
